    pub fn uses_secure_cookies(&self) -> bool {
        self.config.allowed_origin.starts_with("https://")
    }

    pub fn enforce_csrf(
        &self,
        method: &Method,
        headers: &HeaderMap,
        session: &AuthenticatedSession,
    ) -> Result<(), SessionError> {
        if !matches!(
            *method,
            Method::POST | Method::PUT | Method::PATCH | Method::DELETE
        ) {
            return Ok(());
        }

        let origin = headers
            .get(ORIGIN)
            .and_then(|value| value.to_str().ok())
            .ok_or(SessionError::Forbidden)?;
        if origin != self.config.allowed_origin.as_ref() {
            return Err(SessionError::Forbidden);
        }
        let fetch_site = headers
            .get(FETCH_SITE_HEADER)
            .and_then(|value| value.to_str().ok())
            .ok_or(SessionError::Forbidden)?;
        if !matches!(fetch_site, "same-origin" | "same-site") {
            return Err(SessionError::Forbidden);
        }
        let csrf = headers
            .get(CSRF_HEADER)
            .and_then(|value| value.to_str().ok())
            .map(CsrfToken::from_encoded)
            .ok_or(SessionError::Forbidden)?;
        if !self.secret_key.validate_csrf_token(&session.token, &csrf) {
            return Err(SessionError::Forbidden);
        }
        Ok(())
    }

    pub async fn logout_current(&self, session: &AuthenticatedSession) -> Result<(), SessionError> {
        let now = (self.clock)();
        let mut transaction = self.pool.begin().await?;
        sqlx::query("UPDATE sessions SET revoked_at = ? WHERE id = ? AND revoked_at IS NULL")
            .bind(now)
            .bind(session.id)
            .execute(&mut *transaction)
            .await?;
        insert_logout_audit(
            &mut transaction,
            session.user.id,
            "auth.session.logout",
            now,
        )
        .await?;
        transaction.commit().await?;
        Ok(())
    }

    pub async fn logout_all(&self, session: &AuthenticatedSession) -> Result<(), SessionError> {
        let now = (self.clock)();
        let mut transaction = self.pool.begin().await?;
        sqlx::query(
            "UPDATE sessions SET revoked_at = ?
             WHERE user_id = ? AND revoked_at IS NULL",
        )
        .bind(now)
        .bind(session.user.id)
        .execute(&mut *transaction)
        .await?;
        insert_logout_audit(
            &mut transaction,
            session.user.id,
            "auth.session.logout_all",
            now,
        )
        .await?;
        transaction.commit().await?;
        Ok(())
    }
