pub struct AvailabilitySlot {
    pub start: String,
    pub end: String,
    pub status: String, // "free", "busy", "tbd"
}

#[derive(Debug, Serialize)]
pub struct EventOutput {
    pub event: EventSummary,
    pub access: String,
}

#[derive(Debug, Serialize)]
pub struct EventSummary {
    pub id: i64,
    pub calendar_id: i64,
